import { createEntryPayload } from "./page";

export const EntriesPage = () => {
  const payload = createEntryPayload({
    entryId: "entry-1",
    name: "Draft",
    tags: ["new"],
    enabled: true,
  });

  return <pre>{JSON.stringify(payload)}</pre>;
};

/**
 * @summary 항목 생성 payload 계약
 */
interface CreateEntryPayload {
  /**
   * @field 생성할 항목 ID
   */
  entryId: string;
  /**
   * @field 공백을 정리할 항목 이름
   */
  name: string;
  /**
   * @field 항목에 지정할 태그 목록
   */
  tags: string[];
  /**
   * @field 항목 활성화 여부
   */
  enabled: boolean;
}

/**
 * @helper 화면 전용 항목 생성 payload 정규화
 */
export const createEntryPayload = (
  params: CreateEntryPayload,
): CreateEntryPayload => {
  const { entryId, name, tags, enabled } = params;

  return {
    entryId,
    name: name.trim(),
    tags,
    enabled,
  };
};
